// import and run Promise polyfill first
import { polyfill as PromisePolyfill } from "es6-promise";
PromisePolyfill();

// Imports and registers
import { HMIWebExperionServicesAlarmHelp } from "@hw/experionservices/unbundled/HMIWebExperionServicesAlarmHelp";
import { AlarmHelpElement } from "@hw/hmiweb-alarmhelp/unbundled/index";
import { HmiwebTsLogger } from "@hw/hmiweb-core/js/logging/HmiwebTsLogger";
import { HmiwebTsLocalisation } from "@hw/hmiweb-core/js/localisation/HmiwebTsLocalisation";

let service = new HMIWebExperionServicesAlarmHelp();
service.register(HmiwebTsLogger.simpleInstance);
AlarmHelpElement.register(HmiwebTsLogger.instance, HmiwebTsLocalisation.instance, service.alarmHelpService);

window.addEventListener("unload", () => {
    service.dispose();
    service = null;
});
